function gm3_similarity(string $a,string $b): array {
    $aa=array_values(array_unique(ggr_tokens($a)));$bb=array_values(array_unique(ggr_tokens($b)));
    $as=array_fill_keys($aa,true);$bs=array_fill_keys($bb,true);$shared=count(array_intersect_key($as,$bs));$union=count($as+$bs);
    return [$union?$shared/$union:0.0,$shared,count($aa),count($bb)];
}
function gm3_sym_qualifier_conflict(array $a,array $b): bool {
