    foreach(array_keys($qa) as $q)if(!isset($qb[$q]))return true;foreach(array_keys($qb) as $q)if(!isset($qa[$q]))return true;return false;
}
function gm3_target_index(array $targetSet,array $localNames,array $hotels): array {
