    usort($rank,static fn($a,$b)=>$b['score']<=>$a['score'] ?: $b['shared']<=>$a['shared'] ?: $a['local_hotel_id']<=>$b['local_hotel_id']);return $rank;
}
function gm3_anex_geo_model(PDO $db,array $hotels): array {
