function gm3_accept_rank(array $rank,array $sourceNames,array $targetNames,array $source,array $target,array $geoModel): ?array {
    $best=$rank[0]??null;if(!$best)return null;$second=(float)($rank[1]['score']??0);$margin=(float)$best['score']-$second;
