    return ['best'=>$best,'second_score'=>round($second,6),'margin'=>round($margin,6),'geo_evidence'=>$geo,'target'=>mbr_row_target($target),'name_evidence'=>'provider_to_provider_fuzzy_unique_large_margin'];
}
